import java.util.ArrayList;
import java.util.List;

public class Solution {
    static class Node {
        int val;
        Node prev, next;
        Node(int val) { this.val = val; }
    }

    static class DList {
        private final Node head = new Node(0), tail = new Node(0);
        private int size;

        DList() { head.next = tail; tail.prev = head; }

        private Node insertAfter(Node anterior, int v) {
            Node n = new Node(v);
            n.prev = anterior;
            n.next = anterior.next;
            anterior.next.prev = n;
            anterior.next = n;
            size++;
            return n;
        }

        Node addFirst(int v) { return insertAfter(head, v); }
        Node addLast(int v) { return insertAfter(tail.prev, v); }

        // O(1): religa os vizinhos; as sentinelas garantem que prev e next existem.
        void remove(Node n) {
            n.prev.next = n.next;
            n.next.prev = n.prev;
            n.prev = n.next = null;
            size--;
        }

        int size() { return size; }

        List<Integer> toList() {
            List<Integer> out = new ArrayList<>();
            for (Node n = head.next; n != tail; n = n.next) out.add(n.val);
            return out;
        }

        List<Integer> toListReverso() {
            List<Integer> out = new ArrayList<>();
            for (Node n = tail.prev; n != head; n = n.prev) out.add(n.val);
            return out;
        }
    }
}

