import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.List;

class SolutionTest {
    @Test void adicionaNasDuasPontas() {
        var l = new Solution.DList();
        l.addLast(2); l.addLast(3); l.addFirst(1);
        assertEquals(List.of(1, 2, 3), l.toList());
        assertEquals(List.of(3, 2, 1), l.toListReverso());
        assertEquals(3, l.size());
    }

    @Test void removeMeioPontasEUnico() {
        var l = new Solution.DList();
        var a = l.addLast(1); var b = l.addLast(2); var c = l.addLast(3);
        l.remove(b);
        assertEquals(List.of(1, 3), l.toList());
        l.remove(a);
        l.remove(c);
        assertEquals(List.of(), l.toList());
        assertEquals(List.of(), l.toListReverso());
        assertEquals(0, l.size());
    }

    @Test void removerEmMassaEhRapido() {
        var l = new Solution.DList();
        var nos = new Solution.Node[200_000];
        for (int i = 0; i < nos.length; i++) nos[i] = l.addLast(i);
        for (int i = 0; i < nos.length; i += 2) l.remove(nos[i]);
        assertEquals(100_000, l.size());
        assertEquals(1, l.toList().get(0));
    }
}
